* glue.s - integration of the (relocated, patched) arcade program with the Neo Geo runtime.
*
*   game_main   : entered from USER (demo/title request): sets up the I/O shadow and jumps to the
*                 arcade reset entry 0x2400 (its SSP is relocated to ARC_WRAM+0x3F80 by the patcher).
*   frame_hook  : called from our VBlank handler after SYSTEM_IO: feeds the inputs, runs the arcade
*                 VBlank handler (0x2F8C) on the runtime stack, then syncs palette/tiles/sprites.
*   mcu_frame   : in mcu.s.
*   oracle stubs: generated by tools/mkrom.py into build/stubs.s.

        .include "neogeo.i"
        .include "ram.i"

        .text
        .global game_main, sound_init, frame_hook, trap1_handler, main_wait, arc_sound_tick, srch_hook, night_banks
        .global delay_long, delay_short

        .equ    ARC_RESET,      0x2400
        .equ    ARC_IRQ6,       0x2F8C
        .equ    ARC_SNDSEQ,     0x14122         /* sound sequencer, called by the arcade interrupt at 0x2FFE */
        .equ    ARC_WRAM_STACK, ARC_WRAM+0x3F80

* ---- arcade input word (700002/3), active low ----
        .equ    ARC_P1_UP,      0
        .equ    ARC_P1_DOWN,    1
        .equ    ARC_P1_RIGHT,   2
        .equ    ARC_P1_LEFT,    3
        .equ    ARC_P1_GEAR,    4
        .equ    ARC_P1_ACCEL,   5
        .equ    ARC_COIN1,      6
        .equ    ARC_COIN2,      7
        .equ    ARC_START1,     14
        .equ    ARC_START2,     15

sound_init:
        jmp     snd_init

game_main:
        bsr     io_init
        clr.b   rt_in_game
        clr.b   rt_gear
        clr.b   rt_coin_pulse
        clr.b   rt_start_pulse
        clr.b   rt_start_req
        bsr     selftest_decrypt
        st      rt_arcade_on
        jmp     ARC_RESET

* I/O shadow defaults: DSW = 0xFFDF (MAME defaults: joystick, 2 sticks, normal, demo sounds on, 1C/1C),
* inputs idle, SYSTEM idle, wheel idle.
io_init:
        move.w  #0xFFDF,IO_DSW
        move.w  #0xFFFF,IO_P1P2
        move.w  #0x00FF,IO_WHEEL
        move.w  #0xFFF3,IO_SYSTEM
        rts

* Build the arcade input word from the Neo Geo controls (BIOS_P1CURRENT: bit0 up,1 down,2 left,3 right,
* 4 A,5 B,6 C,7 D, active high after SYSTEM_IO).  A = accelerate, B = gear toggle, C = accelerate too.
io_update:
        move.w  #0xFFFF,d0              /* idle (the gear bit 4 is set below) */
        move.b  REG_P1CNT,d1            /* the joystick as it is now (BIOS_P1CURRENT is the VBlank's copy: */
        not.b   d1                      /* a tick run later in the frame saw the press a frame late) */
        btst    #0,d1
        beq.s   1f
        bclr    #ARC_P1_UP,d0
1:      btst    #1,d1
        beq.s   2f
        bclr    #ARC_P1_DOWN,d0
2:      btst    #2,d1
        beq.s   3f
        bclr    #ARC_P1_LEFT,d0
3:      btst    #3,d1
        beq.s   4f
        bclr    #ARC_P1_RIGHT,d0
4:      move.b  d1,d2
        and.b   #0x50,d2                /* A or C */
        beq.s   5f
        bclr    #ARC_P1_ACCEL,d0
5:      /* gear toggle on B press (edge) */
        move.b  d1,d2
        and.b   #0x20,d2
        move.b  rt_prev_b,d3
        move.b  d2,rt_prev_b
        tst.b   d3
        bne.s   6f
        tst.b   d2
        beq.s   6f
        eori.b  #1,rt_gear
6:      tst.b   rt_gear                 /* the gear lever reads 0 at power-on (MAME: toggle, active high,
                                           reversed; the arcade's own variable C1F6 shows it): the attract
                                           demo was recorded in that gear - in the other one the car drove
                                           off its line and crashed */
        bne.s   7f
        bclr    #ARC_P1_GEAR,d0
7:      /* ---- credits: on MVS the BIOS owns them (backup RAM 0xD00034, BCD); mirror every increment
           into the arcade as a coin pulse so its own counter stays in sync ---- */
        tst.b   BIOS_MVS_FLAG
        beq     8f
        move.b  0xD00034,d1
        cmp.b   rt_bios_cred,d1
        beq     8f
        move.b  d1,d2
        sub.b   rt_bios_cred,d2         /* BCD difference is fine for small steps */
        move.b  d1,rt_bios_cred
        tst.b   d2
        ble     8f
        add.b   d2,rt_coins_due
8:      /* SELECT = coin (AES and MVS: the arcade counts it; on MVS the coin slots work too) */
        move.b  BIOS_STATCURNT,d1
        and.b   #0x02,d1                /* P1 SELECT */
        move.b  rt_prev_sel,d2
        move.b  d1,rt_prev_sel
        tst.b   d2
        bne.s   82f
        tst.b   d1
        beq.s   82f
        addq.b  #1,rt_coins_due
82:     /* PLAYER_START seen: hold START until the arcade takes a credit (no credit: nothing happens, as on
           the arcade - the coin is SELECT) */
        tst.b   rt_start_req
        beq     9f
        clr.b   rt_start_req
        moveq   #1,d1
81:     move.b  d1,rt_start_wait
        move.w  #240,rt_start_hold
        move.w  ARC_WRAM+0x1EE,rt_cred_start
9:      /* coin pulse: 3 frames pressed, 12 released */
        move.b  rt_coin_seq,d1
        bne     91f
        tst.b   rt_coins_due
        beq     92f
        subq.b  #1,rt_coins_due
        moveq   #1,d1
91:     cmpi.b  #3,d1
        bhi     93f
        bclr    #ARC_COIN1,d0
93:     addq.b  #1,d1
        cmpi.b  #15,d1
        bcs     94f
        moveq   #0,d1
94:     move.b  d1,rt_coin_seq
92:     /* START: raw button, or the hold after PLAYER_START */
        move.b  BIOS_STATCURNT,d1
        btst    #0,d1
        beq     10f
        bclr    #ARC_START1,d0
10:     tst.w   rt_start_hold
        beq     11f
        tst.b   rt_start_wait
        beq     101f
        subq.b  #1,rt_start_wait
        bra     11f
101:    move.w  ARC_WRAM+0x1EE,d1
        cmp.w   rt_cred_start,d1
        bcs     102f                    /* the arcade took the credit: done */
        subq.w  #1,rt_start_hold
        move.w  rt_start_hold,d1
        btst    #3,d1                   /* 8 frames pressed, 8 released: the arcade wants a fresh edge */
        bne     11f
        bclr    #ARC_START1,d0
        bra     11f
102:    clr.w   rt_start_hold
11:     move.w  d0,IO_P1P2
        rts

* frame_hook: runs inside our VBlank handler (all registers saved by the caller)
* ------------------------------------------------------------------------------------------
* main_wait: replaces every "tst.w C1A6 / beq.s *-6" loop of the arcade (wait for the next interrupt
* tick).  Runs a tick that the VBlank held back because the frame was not finished (see irq_vblank),
* otherwise waits for the next one.  Preserves all registers; the code after it clears C1A6 as before.
* ------------------------------------------------------------------------------------------
main_wait:
        move.w  REG_LSPCMODE,rt_dbg+14  /* profiling */
        clr.b   rt_mw_age
        move    sr,-(sp)
        ori     #0x0700,sr
        tst.b   rt_tick_pend
        bne.s   2f
        st      rt_mwait                /* (with the interrupts masked: no tick can be held back in between) */
        move    (sp)+,sr
1:      addq.l  #1,rt_idle              /* profiling: 54 cycles per iteration */
        tst.w   ARC_WRAM+0x1A6
        beq.s   1b
        sf      rt_mwait
        rts
2:      subq.b  #1,rt_tick_pend
        st      rt_in_hook              /* a VBlank meanwhile only flushes the VRAM (irq_vblank) */
        move    (sp),sr
        movem.l d0-d7/a0-a6,-(sp)
        jsr     frame_hook
        clr.b   rt_in_hook
        movem.l (sp)+,d0-d7/a0-a6
        move    (sp)+,sr
        rts

* ------------------------------------------------------------------------------------------
* srch_hook (jmp at 0xA07A): the arcade looks for the record of key d0 in the table at a1, one compare
* per record ("cmp.w (a1),d0 / beq / skip to $00FF / next").  With the index of tools/mksrch.py the
* record is found at once; anything not in the index takes the original loop.  Continues at 0xA08C with
* a1 -> the key word, as the original; only a1 changes.
* ------------------------------------------------------------------------------------------
srch_hook:
        cmpi.w  #64,d0
        bcc.s   9f
        movem.l d0-d1/a0,-(sp)
        lea     srch_tabs,a0
        moveq   #3,d1
1:      cmpa.l  (a0)+,a1
        beq.s   2f
        dbra    d1,1b
        bra.s   8f                      /* not one of the four tables */
2:      neg.w   d1
        addq.w  #3,d1                   /* table number */
        lsl.w   #8,d1
        and.w   #0x3F,d0
        lsl.w   #2,d0
        add.w   d0,d1
        lea     srch_idx,a0
        move.l  (a0,d1.w),d1
        beq.s   8f                      /* not indexed: the loop */
        movea.l d1,a1
        movem.l (sp)+,d0-d1/a0
        jmp     0xA08C
8:      movem.l (sp)+,d0-d1/a0
9:      cmp.w   (a1),d0                 /* the original loop */
        beq.s   1f
2:      addq.l  #2,a1
        cmpi.w  #0xFF,(a1)
        bne.s   2b
        addq.l  #2,a1
        bra.s   9b
1:      jmp     0xA08C
srch_tabs:
        .long   0xE15B2, 0xE1A12, 0xE1382, 0xE17E2
srch_idx:
        .include "srch_idx.inc"

* ------------------------------------------------------------------------------------------
* night_banks (jmp at 0x8A60, a1 = FEF87E): the night stages build palette banks 6..0 of the arcade, each
* one step darker than the previous (0x203000 down to 0x200000; the tiles show bank 0, the headlight
* sprites pick brighter ones).  The port keeps arcade palette RAM 200000-200FFF (banks 0 and 1) and bank
* 7 only: the same loop with the bank address kept as an arcade address, storing only what is kept
* (before, banks 2-6 were written over the RAM that follows the palette shadow: I/O, sprite pools and
* VRAM queue - a black screen).  Same registers at the end as the original.
* ------------------------------------------------------------------------------------------
night_banks:
        move.l  d3,-(sp)
        movea.l #0x203000,a2            /* bank 6, arcade address */
        move.w  #6,d6
1:      move.l  a1,d5
2:      move.w  (a1),d4
        move.w  d4,d0
        andi.w  #0x000F,d0
        subq.w  #1,d0
        bcc.s   3f
        clr.w   d0
3:      move.w  d4,d1
        andi.w  #0x00F0,d1
        subi.w  #0x0010,d1
        bcc.s   4f
        clr.w   d1
4:      move.w  d4,d2
        andi.w  #0x0F00,d2
        subi.w  #0x0100,d2
        bcc.s   5f
        clr.w   d2
5:      or.w    d2,d1
        or.w    d1,d0
        cmpa.l  #0x201000,a2
        bcc.s   6f                      /* banks 2-6: not kept */
        move.l  a2,d3
        sub.l   #0x200000-ARC_PALRAW,d3
        exg     d3,a2
        move.w  d0,(a2)
        exg     d3,a2
6:      addq.l  #2,a2
        move.w  d0,(a1)+
        cmpa.l  #ARC_WRAM+0x3E7E,a1     /* FEFE7E */
        blt.s   2b
        suba.l  #0x600,a1
        suba.l  #0xE00,a2
        dbra    d6,1b
        suba.l  #0x200000-ARC_PALRAW,a2
        move.l  (sp)+,d3
        rts

* ------------------------------------------------------------------------------------------
* delay_long / delay_short (jmp at 0x2F70 / 0x2F7E): the arcade's busy-wait delays, d1+1 units of a dbra
* loop (65521 / 4081 iterations: about 655,000 / 40,800 cycles, 54.6 / 3.4 ms at 12 MHz).  They set
* the speed of the fades and of some screens.  On the Neo Geo the VBlank work of the port takes part of
* those cycles, so the same loop lasted longer (much longer on hardware): the time is measured with the
* raster line counter instead (768 cycles a line), so the delays last what they last on the arcade.
* Returns d0.w = d1.w = $FFFF like the loops.
* ------------------------------------------------------------------------------------------
delay_long:
        move.l  #655226,d0
        bra.s   delay_units
delay_short:
        move.l  #40834,d0
delay_units:
        movem.l d2-d4,-(sp)
        moveq   #0,d2
        move.w  d1,d2
        addq.l  #1,d2                   /* units */
        move.l  d0,d3
        swap    d3
        mulu    d2,d3
        swap    d3
        clr.w   d3
        mulu    d2,d0
        add.l   d3,d0                   /* cycles to wait */
        move.w  REG_LSPCMODE,d3
        lsr.w   #7,d3                   /* line (0xF8..0x1FF) */
1:      move.b  d0,REG_WATCHDOG
        move.w  REG_LSPCMODE,d4
        lsr.w   #7,d4
        move.w  d4,d2
        sub.w   d3,d2                   /* lines since the last read */
        bpl.s   2f
        add.w   #264,d2                 /* past the last line: the counter went back to 0xF8 */
2:      move.w  d4,d3
        mulu    #768,d2
        sub.l   d2,d0
        bgt.s   1b
        movem.l (sp)+,d2-d4
        moveq   #-1,d0
        moveq   #-1,d1
        rts

* arc_sound_tick: the arcade sound sequencer (called once per arcade interrupt at 0x2FFE, moved here so
* that it runs every VBlank even when a tick is held back)
arc_sound_tick:
        tst.b   rt_arcade_on
        beq.s   1f
        tst.b   rt_in_hook
        bne.s   2f
        movem.l d0-d7/a0-a6,-(sp)
        jsr     ARC_SNDSEQ
        movem.l (sp)+,d0-d7/a0-a6
1:      rts
2:      /* a tick of the arcade is running: as on the arcade (the sequencer is part of its interrupt), it
           must not be interrupted by the sequencer - frame_hook runs it when the tick ends */
        cmpi.b  #3,rt_snd_owed
        bcc.s   1b
        addq.b  #1,rt_snd_owed
        rts

frame_hook:
        move.w  REG_LSPCMODE,rt_dbg     /* profiling: raster counter at each milestone */
        addq.l  #1,rt_ticks
        bsr     frame_begin
        bsr     io_update
        /* run the arcade IRQ handler on the runtime stack with a fake exception frame */
        move.l  sp,rt_saved_sp
        lea     RT_STACK,sp
        pea     arc_irq_done
        move    sr,-(sp)
        jmp     ARC_IRQ6
arc_irq_done:
        move.w  REG_LSPCMODE,rt_dbg+2
        st      rt_pal_ahead            /* from here ARC_PAL is this tick's: a VBlank meanwhile keeps it back */
        bsr     palette_sync
        move.w  REG_LSPCMODE,rt_dbg+4
        bsr     video_frame
        move.w  REG_LSPCMODE,rt_dbg+6
        bsr     diag_frame
        bsr     frame_seal
        clr.b   rt_pal_ahead
1:      tst.b   rt_snd_owed             /* sequencer runs held back during this tick */
        beq.s   2f
        subq.b  #1,rt_snd_owed
        jsr     ARC_SNDSEQ
        bra.s   1b
2:      move.l  rt_saved_sp,sp
        rts

* frame_begin: the sprite set this frame fills - the one the frame still waiting to be shown does not use.
* With two frames waiting (the main loop catching up), the older is dropped: its commands go out with
* the next one, its sprites are not shown.  Trashes d0.
frame_begin:
        clr.b   rt_spr_conv
        move    sr,-(sp)
        ori     #0x0700,sr
        cmpi.b  #2,rt_pend_n
        bcs.s   1f
        move.l  rt_pend_q+4,rt_pend_q
        move.b  rt_pend_s+1,rt_pend_s
        subq.b  #1,rt_pend_n
1:      tst.b   rt_pend_n
        beq.s   2f
        moveq   #1,d0
        sub.b   rt_pend_s,d0            /* (a waiting frame without sprites, 0xFF, leaves the set as is) */
        bcs.s   2f
        move.b  d0,rt_fill_set
2:      move    (sp)+,sr
        tst.b   rt_fill_set
        bne.s   3f
        move.l  #SPR_F0,rt_set_base
        move.l  #EFF_DESC,rt_eff_base
        rts
3:      move.l  #SPR_SET1,rt_set_base
        move.l  #EFF_SET1,rt_eff_base
        rts

* frame_seal: the frame is complete - its commands end at rt_vcmd_ptr, its sprites are in the set filled
* (0xFF: the arcade did not convert its sprite lists this time, the screen keeps the sprites it has).
* Trashes d0-d1/a0.
frame_seal:
        move    sr,-(sp)
        ori     #0x0700,sr
        moveq   #-1,d0
        tst.b   rt_spr_conv
        beq.s   1f
        moveq   #0,d0
        move.b  rt_fill_set,d0
        lea     rt_set_cnt,a0
        move.w  d0,d1
        lsl.w   #3,d1
        adda.w  d1,a0
        move.w  rt_spr_n0,(a0)+
        move.w  rt_spr_n1,(a0)+
        move.w  rt_eff_n,(a0)
1:      moveq   #0,d1
        move.b  rt_pend_n,d1            /* 0 or 1 (frame_begin) */
        lea     rt_pend_s,a0
        move.b  d0,(a0,d1.w)
        lsl.w   #2,d1
        lea     rt_pend_q,a0
        move.l  rt_vcmd_ptr,(a0,d1.w)
        addq.b  #1,rt_pend_n
        clr.b   rt_noseal
        move    (sp)+,sr
        rts

* ------------------------------------------------------------------------------------------
* Diagnostic overlay (hold D for one second to toggle it): the protection sums and sabotage flags of
* the arcade program and the ticks skipped, on the fix layer.  "OK" / "MAL" compares a sum with the
* value of the original program.  Queued like any other VRAM change.
* ------------------------------------------------------------------------------------------
        .equ    DIAG_N, 21
diag_frame:
        move.b  BIOS_P1CURRENT,d0
        btst    #7,d0
        beq.s   1f
        addq.b  #1,rt_diag_hold
        cmpi.b  #60,rt_diag_hold
        bne.s   2f
        not.b   rt_diag_on
        bne.s   2f
        st      rt_diag_clr
        bra.s   2f
1:      clr.b   rt_diag_hold
2:      tst.b   rt_diag_on
        bne.s   3f
        tst.b   rt_diag_clr
        bne.s   3f
        rts
3:      movea.l rt_vcmd_ptr,a6
        cmpa.l  #VCMD_BUF,a6
        bcc.s   4f
        lea     VCMD_BUF,a6
4:      lea     diag_tab,a0
        moveq   #0,d7                   /* line */
dg_line:
        jsr     vc_room
        move.w  d7,d0
        addq.w  #7,d0                   /* row (below the HUD) */
        add.w   #VRAM_FIX+2*32,d0       /* column 2 */
        move.w  d0,(a6)+
        move.w  #32,(a6)+
        move.w  #17-1,(a6)+
        tst.b   rt_diag_on
        bne.s   5f
        moveq   #16,d0                  /* turned off: blank the line */
6:      move.w  #0x00FF,(a6)+
        dbra    d0,6b
        lea     14(a0),a0
        bra     dg_next
5:      moveq   #3,d0                   /* label */
7:      moveq   #0,d1
        move.b  (a0)+,d1
        or.w    #(PAL_FIX<<12)&0xFFFF,d1
        move.w  d1,(a6)+
        dbra    d0,7b
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        movea.l (a0)+,a1                /* address */
        move.w  (a0)+,d1                /* size: 1, 2 or 4 */
        move.l  (a0)+,d4                /* expected (0 = none) */
        moveq   #0,d2
        cmpi.w  #4,d1
        bne.s   8f
        move.l  (a1),d2
        moveq   #7,d3
        bra.s   10f
8:      move.w  (a1),d2
        swap    d2
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        moveq   #3,d3
10:     rol.l   #4,d2
        moveq   #15,d0
        and.w   d2,d0
        move.b  diag_hex(pc,d0.w),d0
        or.w    #(PAL_FIX<<12)&0xFFFF,d0
        move.w  d0,(a6)+
        dbra    d3,10b
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        lea     diag_none(pc),a2
        tst.l   d4
        beq.s   11f
        lea     diag_ok(pc),a2
        cmp.l   (a1),d4
        beq.s   11f
        lea     diag_bad(pc),a2
11:     moveq   #2,d0
12:     moveq   #0,d1
        move.b  (a2)+,d1
        or.w    #(PAL_FIX<<12)&0xFFFF,d1
        move.w  d1,(a6)+
        dbra    d0,12b
dg_next:
        addq.w  #1,d7
        cmpi.w  #DIAG_N,d7
        bcs     dg_line
        move.l  a6,rt_vcmd_ptr
        tst.b   rt_diag_on
        bne.s   13f
        clr.b   rt_diag_clr
13:     rts
diag_hex:
        .ascii  "0123456789ABCDEF"
diag_ok:
        .ascii  " OK"
diag_bad:
        .ascii  "MAL"
diag_none:
        .ascii  "   "
        .align  2
* label (4 chars), address, size, expected value of the original program (0 = not checked)
diag_tab:
        .ascii  "F502"
        .long   ARC_WRAM+0x3502
        .word   4
        .long   0x14AA816C
        .ascii  "F520"
        .long   ARC_WRAM+0x3520
        .word   4
        .long   0xAFC9EA39
        .ascii  "F53C"
        .long   ARC_WRAM+0x353C
        .word   4
        .long   0xC7542125
        .ascii  "F540"
        .long   ARC_WRAM+0x3540
        .word   4
        .long   0x67CE546B
        .ascii  "F846"
        .long   ARC_WRAM+0x3846
        .word   4
        .long   0x1CF15E75
        .ascii  "F80C"
        .long   ARC_WRAM+0x380C
        .word   4
        .long   0
        .ascii  "SUMK"
        .long   0xF0A00
        .word   4
        .long   0
        .ascii  "F81E"
        .long   ARC_WRAM+0x381E
        .word   4
        .long   0xA209E4F1
        .ascii  "F54E"
        .long   ARC_WRAM+0x354E
