* TRAP #1: dispatch an arcade VRAM write (2/4-byte instruction replaced by the trap) to its stub.
* Stack on entry: SR.w, PC.l (PC = address after the trap opcode).
        .global trap1_handler
trap1_handler:
        movem.l d0-d1/a0-a1,-(sp)
        move.l  18(sp),a0               /* return PC */
        lea     trap_table,a1
1:      move.l  (a1),d0
        beq     trap_error_pc
        cmp.l   d0,a0
        beq     2f
        lea     12(a1),a1
        bra     1b
2:      move.l  8(a1),d0
        add.l   d0,18(sp)               /* skip the padding after the trap */
        move.l  4(a1),rt_trap_stub
        movem.l (sp)+,d0-d1/a0-a1
        pea     trap1_rte
        move.l  rt_trap_stub,-(sp)
        rts                             /* -> stub, which returns to trap1_rte */
trap1_rte:
        rte
trap_error_pc:
        movem.l (sp)+,d0-d1/a0-a1
        jmp     trap_error

* palette_sync: arcade palette RAM shadow (xBRG444, entries 0..1023) -> ARC_PAL (Neo Geo format) for
* the 16-colour palettes whose raw words changed since the last call.  A quarter of the 64 palettes is
* checked per call (the palettes hardly change during a race); when one of them changed, the other
* three quarters are checked too in the same call (a fade or a new screen changes them all at once).
* The compare is 8 cmpm.l per palette with an early exit on the first difference.
palette_sync:
        lea     pal_table,a4
        moveq   #0,d0
        move.b  rt_pal_half,d0
        addq.b  #1,d0
        and.b   #3,d0
        move.b  d0,rt_pal_half          /* quarter checked by this call */
        moveq   #0,d5                   /* palettes converted */
        bsr.s   ps_quarter
        cmpi.b  #1,ARC_WRAM+0x1B3       /* outside a race: every quarter, every frame (a palette written in */
        bne.s   1f                      /* another quarter showed its new sprites black for up to 3 frames) */
        cmpi.w  #2,d5                   /* in a race (a colour cycle changes one palette every frame): the */
        bcs.s   9f                      /* others only when two changed */
1:      addq.b  #1,d0                   /* the other quarters as well - a fade then darkens the
                                           whole screen at once (with ">= 2 changed" a quarter holding a
                                           single palette of the fade left the others up to 3 frames behind) */
        and.b   #3,d0
        cmp.b   rt_pal_half,d0
        beq.s   9f
        bsr.s   ps_quarter
        bra.s   1b
9:      rts
* ps_quarter: d0.b = quarter 0..3 (palettes 16*q .. 16*q+15).  d5 += palettes converted.  Keeps d0/a4.
ps_quarter:
        move.w  d0,d1
        lsl.w   #8,d1
        add.w   d1,d1                   /* q * 512 bytes */
        lea     ARC_PALRAW,a0
        adda.w  d1,a0
        lea     ARC_PALLAST,a1
        adda.w  d1,a1
        lea     ARC_PAL,a2
        adda.w  d1,a2
        lea     rt_pal_dirty,a3
        move.w  d0,d1
        lsl.w   #4,d1
        adda.w  d1,a3
        moveq   #15,d7
ps_pal:
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        lea     32(a2),a2
        addq.l  #1,a3
        dbra    d7,ps_pal
        rts
ps_conv:
        /* back to the start of this palette and convert its 16 entries (a1 is past the differing long,
           which may be the last one of the palette: step back before rounding down) */
        move.l  a1,d1
        subq.l  #4,d1
        sub.l   #ARC_PALLAST,d1
        and.w   #0xFFE0,d1
        lea     ARC_PALLAST,a1
        adda.l  d1,a1
        lea     ARC_PALRAW,a0
        adda.l  d1,a0
        moveq   #15,d6
1:      move.w  (a0)+,d1
        move.w  d1,(a1)+
        and.w   #0x0FFF,d1
        add.w   d1,d1
        move.w  (a4,d1.w),(a2)+
        dbra    d6,1b
        st      (a3)+
        st      rt_pal_any
        addq.w  #1,d5
        dbra    d7,ps_pal
        rts

* selftest_decrypt: decrypt a few known pairs into rt_test_out so the MAME harness can check decrypt_long
selftest_decrypt:
        lea     test_vals(pc),a0
        lea     rt_test_out,a1
        moveq   #5,d1
1:      move.l  (a0)+,d0
        jsr     decrypt_long
        move.l  d0,(a1)+
        dbra    d1,1b
        rts
test_vals:
        .long   0x4D0FF8A6, 0x40544454, 0x095DB400, 0x4054EBE5, 0x3A3F3D18, 0xC8411F0E
        .align  2

* ------------------------------------------------------------------------------------------
* Fast replacements for the arcade routines that write whole blocks of tiles (patched at their
* entry with `jmp` by tools/mkrom.py).  Same register effects as the originals.
* ------------------------------------------------------------------------------------------
        .global blk_copy_l1, blk_copy_l0, clear_l1, clear_l0

* 0x11CF4 / 0x11D62: draw image block d0 at position d4 (row<<8 | column) into layer 1 / layer 0.
* Header (decrypted): bits 0-7 height, 8-15 width, 16-31 offset into the data region.
blk_copy_l1:
        movem.l d5-d7/a0/a3/a6,-(sp)
        lea     0xE5674,a1
        movea.l ARC_WRAM+0x2C3C,a2
        lsl.b   #2,d4
        addi.b  #0x14,d4
        addi.l  #0x102000,d4
        lea     0x1030C0,a3
        moveq   #1,d7                   /* clip at the end of VRAM like the original */
        bra     blk_common
blk_copy_l0:
        movem.l d5-d7/a0/a3/a6,-(sp)
        lea     0xEA1BE,a1
        movea.l ARC_WRAM+0x2C48,a2
        lsl.b   #2,d4
        addi.l  #0x100014,d4
        lea     0x1010A0,a3
        moveq   #0,d7
blk_common:
        lsl.w   #2,d0
        move.l  (a1,d0.w),d0
        move.l  d0,(a3)                 /* the original parks the header in a VRAM cell and reads it back */
        moveq   #0,d3
        move.b  d0,d3                   /* height */
        lsr.w   #8,d0
        moveq   #0,d2
        move.b  d0,d2                   /* width */
        swap    d0
        move.w  d0,d1                   /* data offset (16-bit, sign-extended by the original addressing) */
        movea.l d4,a5
        subq.w  #1,d2
        subq.w  #1,d3
        move.w  d2,d6
        /* the cells go straight to the shadow map; the column sprites showing the block's map columns
           where a cell changed are reloaded whole at the next frame (much cheaper than one queued cell
           per tile; a block drawn again unchanged costs nothing).  They are marked after the copy: a
           VBlank during the copy may load a column half written */
        move.l  a5,d0
        and.w   #0x1FFF,d0
        lsr.w   #2,d0
        and.w   #63,d0                  /* first map column */
        move.w  d6,d5                   /* width - 1 */
        st      rt_col_inval
        moveq   #0,d4                   /* block columns with a changed cell (bit j; all if wider than 32) */
        cmpi.w  #32,d6
        bcs.s   1f
        moveq   #-1,d4
1:      lea     rt_col_loaded,a0
        tst.w   d7
        beq.s   blk_row
        lea     24(a0),a0               /* layer 1 */
blk_row:
        movea.l a5,a4
        move.w  d6,d2
blk_col:
        move.l  (a2,d1.w),d5
        cmp.l   (a4),d5
        beq.s   3f
        move.l  d5,(a4)
        move.w  d6,d5
        sub.w   d2,d5
        bset    d5,d4
3:      addq.l  #4,a4
        addq.w  #4,d1
        tst.w   d7
        beq.s   1f
        cmpa.l  #0x104000,a4
        bge.s   blk_done
1:      dbra    d2,blk_col
        adda.l  #0x100,a5
        tst.w   d7
        beq.s   2f
        cmpa.l  #0x104000,a5
        bge.s   blk_done
2:      dbra    d3,blk_row
blk_done:
        tst.l   d4
        beq.s   6f                      /* the block was already there: nothing to reload */
        move.b  #2*NCOLSPR,rt_cl_budget /* the arcade drew a picture: its columns all go in the next frame, */
                                        /* with its palette (spread over frames, the old picture showed */
                                        /* with the new colours: the intro photos flickered) */
        move.w  d6,d5
        moveq   #NCOLSPR-1,d2
4:      move.b  (a0),d3
        cmpi.b  #0xFF,d3
        beq.s   5f
        sub.b   d0,d3
        and.w   #63,d3
        cmp.w   d5,d3
        bhi.s   5f
        btst    d3,d4
        beq.s   5f
        move.b  #0xFF,(a0)              /* a changed column of the block: reload */
        st      rt_col_inval            /* (layer_update checks every column even if the scroll is the same) */
5:      addq.l  #1,a0
        dbra    d2,4b
        moveq   #-1,d3                  /* as the original leaves it */
6:      movem.l (sp)+,d5-d7/a0/a3/a6
        rts

* Map strip copies (patched at 0x9904 / 0x99A0 / 0x9C3C / 0x9CD8 by tools/mkrom.py): the original inner
* block is "dX = C224 & $F0 ; if dX != $90: move.l (a0),(a1) ; step a1" with dX = d7 or d6 and a step of
* 4 (row strip) or $100 (column strip).
        .global strip_h7, strip_v7, strip_h6, strip_v6
* d7 / d6 are scratch there (the arcade reloads them from C224 for every cell and the code after the
* copy sets them again before any use).  A cell that already holds the pair (most of them) is skipped at
* once; a cell of a map column outside the column window only needs the shadow write (rt_c0 only changes
* in video_frame, which cannot run in the middle of the main loop, so no masking is needed); the rest goes
* through vram_store.
        .macro  STRIP reg, vert
        move.l  (a0),\reg
        cmp.l   (a1),\reg
        beq.s   9f
        move.w  ARC_WRAM+0x224,\reg
        andi.w  #0xF0,\reg
        cmpi.w  #0x90,\reg
        beq.s   9f
        move.w  a1,\reg
        lsr.w   #2,\reg
        btst    #11,\reg               /* layer 1 (shadow VRAM + 0x2000) */
        bne.s   1f
        sub.w   rt_c0,\reg
        bra.s   2f
1:      sub.w   rt_c0+2,\reg
2:      andi.w  #63,\reg               /* j = (col - c0) & 63 */
        cmpi.w  #NCOLSPR,\reg
        bcs.s   3f
        move.l  (a0),(a1)
9:
        .if     \vert
        lea     0x100(a1),a1
        .else
        addq.l  #4,a1
        .endif
        rts
3:      bsr     strip_win
        bra.s   9b
        .endm
strip_h7:
        STRIP   d7,0
strip_v7:
        STRIP   d7,1
strip_h6:
        STRIP   d6,0
strip_v6:
        STRIP   d6,1
* Native versions of the four map strip copies (jmp at their loop heads 0x98EC / 0x9988 / 0x9C24 /
* 0x9CC0, tools/mkrom.py): the arcade loops instruction for instruction (same registers, same stack frame
* saved at FEF862, same address helpers 0x9A1A/0x9A38 and 0x9D52/0x9D70), with the per-cell store inline:
* no call per cell, and the C224 test ("& $F0 = $90: store nothing") made once per group of cells, after
* the helper that clobbers d6/d7 (C224 does not change inside the loop).
        .macro  SCELL vert
        tst.b   d6
        bne.s   9f
        move.l  (a0),d7
        cmp.l   (a1),d7
        beq.s   9f
        move.w  a1,d7
        lsr.w   #2,d7
        btst    #11,d7
        bne.s   1f
        sub.w   rt_c0,d7
        bra.s   2f
1:      sub.w   rt_c0+2,d7
2:      andi.w  #63,d7
        cmpi.w  #NCOLSPR,d7
        bcs.s   3f
        move.l  (a0),(a1)
        bra.s   9f
3:      bsr     strip_win
9:
        .if     \vert
        adda.w  #256,a1
        .else
        addq.w  #4,a1
        .endif
        .endm
        .macro  C224FLAG
        move.w  ARC_WRAM+0x224,d6
        andi.w  #0xF0,d6
        cmpi.w  #0x90,d6
        seq     d6
        .endm

        .global nat_h7, nat_v7, nat_h6, nat_v6
nat_h7:                                 /* 0x98EC */
        move.w  d5,-(sp)
        move.w  d3,-(sp)
        move.l  a1,-(sp)
        move.w  d1,-(sp)
        move.l  sp,ARC_WRAM+0x3862
10:     jsr     0x9A1A
11:     move.l  a0,-(sp)
        jsr     0x9A38
        C224FLAG
12:     SCELL   0
        dbra    d5,13f
        bra.s   15f
13:     addq.l  #4,a0
        addi.w  #16,d1
        move.w  d1,d4
        andi.w  #112,d4
        bne     12b
        move.w  d1,d4
        andi.w  #896,d4
        bne.s   14f
        suba.w  #256,a1
14:     movea.l (sp)+,a0
        addq.l  #2,a0
        move.w  d1,d4
        andi.w  #3968,d4
        bne     11b
        bra     10b
15:     movea.l ARC_WRAM+0x3862,sp
        move.w  (sp)+,d1
        addi.w  #16,d2
        movea.l (sp)+,a1
        adda.w  #256,a1
        move.w  a1,d4
        andi.w  #7936,d4
        bne.s   16f
        suba.w  #8192,a1
16:     move.w  (sp)+,d3
        move.w  (sp)+,d5
        dbra    d3,nat_h7
        rts

nat_v7:                                 /* 0x9988 */
        move.w  d5,-(sp)
        move.w  d3,-(sp)
        move.l  a1,-(sp)
        move.w  d2,-(sp)
        move.l  sp,ARC_WRAM+0x3862
10:     jsr     0x9A1A
11:     move.l  a0,-(sp)
        jsr     0x9A38
        C224FLAG
12:     SCELL   1
        dbra    d5,13f
        bra.s   15f
13:     adda.l  #32,a0
        addi.w  #16,d2
        move.w  d2,d4
        andi.w  #112,d4
        bne     12b
        move.w  d2,d4
        andi.w  #384,d4
        bne.s   14f
        suba.w  #8192,a1
14:     movea.l (sp)+,a0
        adda.l  #64,a0
        move.w  d2,d4
        andi.w  #16256,d4
        bne     11b
        bra     10b
15:     movea.l ARC_WRAM+0x3862,sp
        move.w  (sp)+,d2
        addi.w  #16,d1
        movea.l (sp)+,a1
        addq.w  #4,a1
        move.w  a1,d4
        andi.w  #255,d4
        bne.s   16f
        suba.w  #256,a1
16:     move.w  (sp)+,d3
        move.w  (sp)+,d5
        dbra    d3,nat_v7
        rts

nat_h6:                                 /* 0x9C24 */
        move.w  d5,-(sp)
        move.w  d3,-(sp)
        move.l  a1,-(sp)
        move.w  d1,-(sp)
        move.l  sp,ARC_WRAM+0x3862
10:     jsr     0x9D52
11:     move.l  a0,-(sp)
        jsr     0x9D70
        C224FLAG
12:     SCELL   0
        dbra    d5,13f
        bra.s   15f
13:     addq.l  #4,a0
        addi.w  #16,d1
        move.w  d1,d4
        andi.w  #112,d4
        bne     12b
        move.w  d1,d4
        andi.w  #896,d4
        bne.s   14f
        suba.w  #256,a1
14:     movea.l (sp)+,a0
        addq.l  #2,a0
        move.w  d1,d4
        andi.w  #3968,d4
        bne     11b
        bra     10b
15:     movea.l ARC_WRAM+0x3862,sp
        move.w  (sp)+,d1
        addi.w  #16,d2
        movea.l (sp)+,a1
        adda.w  #256,a1
        move.w  a1,d4
        andi.w  #7936,d4
        bne.s   16f
        suba.w  #8192,a1
16:     move.w  (sp)+,d3
        move.w  (sp)+,d5
        dbra    d3,nat_h6
        rts

nat_v6:                                 /* 0x9CC0 */
        move.w  d5,-(sp)
        move.w  d3,-(sp)
        move.l  a1,-(sp)
        move.w  d2,-(sp)
        move.l  sp,ARC_WRAM+0x3862
10:     jsr     0x9D52
11:     move.l  a0,-(sp)
        jsr     0x9D70
        C224FLAG
12:     SCELL   1
        dbra    d5,13f
        bra.s   15f
13:     adda.l  #32,a0
        addi.w  #16,d2
        move.w  d2,d4
        andi.w  #112,d4
        bne     12b
        move.w  d2,d4
        andi.w  #384,d4
        bne.s   14f
        suba.w  #8192,a1
14:     movea.l (sp)+,a0
        adda.l  #64,a0
        move.w  d2,d4
        andi.w  #16256,d4
        bne     11b
        bra     10b
15:     movea.l ARC_WRAM+0x3862,sp
        move.w  (sp)+,d2
        addi.w  #16,d1
        movea.l (sp)+,a1
        addq.w  #4,a1
        move.w  a1,d4
        andi.w  #255,d4
        bne.s   16f
        suba.w  #256,a1
16:     move.w  (sp)+,d3
        move.w  (sp)+,d5
        dbra    d3,nat_v6
        rts

* nat_obj (jmp at 0x4708): the builder of the arcade's sprite list 2 (text and HUD objects, from the
* object list at a0 into a3, count at FEC280).  An object one tile high (most of them: the characters
* of the strings) takes a direct path; any other one runs the original code (transcribed below).  Same memory
* effects; a0/a3/a4/a6 as the original leaves them.
        .global nat_obj
nat_obj:
        lea     ARC_WRAM+0x280,a4
        clr.w   (a4)
no_loop:
        move.w  (a0),d7
        bpl.s   1f
        move.w  #0x8000,(a6)
        rts
1:      tst.w   ARC_WRAM+0x3824         /* flipped screen: the original path */
        bne     no_gen
        move.w  d7,d0
        andi.w  #0x3FF,d0
        add.w   d0,d0
        add.w   d0,d0
        lea     0xD07D6,a1
        cmpi.b  #1,3(a1,d0.w)           /* one row of tiles */
        bne     no_gen
        moveq   #0,d2
        move.b  2(a1,d0.w),d2           /* width */
        beq     no_gen
        subq.w  #1,d2
        moveq   #0,d1
        move.w  (a1,d0.w),d1
        movea.l ARC_WRAM+0x15FC,a2
        adda.l  d1,a2
        move.w  d7,d4
        lsr.w   #8,d4
        andi.b  #0x3C,d4
        lsr.b   #2,d4
        move.b  d4,ARC_WRAM+0x288       /* palette (as the original keeps it) */
        move.w  ARC_WRAM+0x28E8,d6      /* y: (Y0 - (y + 13)) & 255 */
        sub.w   4(a0),d6
        subi.w  #13,d6
        andi.w  #0xFF,d6
        move.w  2(a0),d0                /* x: (x - 69 + 14) & 511, then + 16 a column */
        subi.w  #55,d0
        andi.w  #0x1FF,d0
1:      tst.w   2(a2)
        beq.s   9f
        move.w  (a2),d5
        andi.w  #0xFF00,d5
        or.w    d6,d5
        move.w  d5,(a3)
        move.b  1(a2),d5
        btst    #14,d7
        beq.s   2f
        lsr.b   #2,d5
        andi.b  #0x30,d5
        or.b    d4,d5
        add.b   d5,d5
        add.b   d5,d5
2:      eori.b  #0x20,d5
        lsl.w   #8,d5
        or.w    d0,d5
        move.w  d5,4(a3)
        move.w  2(a2),d5
        addi.w  #0x2E00,d5
        move.w  d5,6(a3)
        addq.l  #8,a3
        addq.w  #1,(a4)
9:      addq.l  #4,a2
        addi.w  #16,d0
        dbra    d2,1b
        addq.l  #6,a0
        bra     no_loop
no_gen:                                 /* 0x471C */
        lea     0xD07D6,a1
        movea.l ARC_WRAM+0x15FC,a2
        clr.l   d0
        move.w  (a0),d0
        andi.w  #0x3FF,d0
        clr.w   d5
        move.b  (a0),d5
        andi.b  #0x3C,d5
        lsr.w   #2,d5
        move.b  d5,ARC_WRAM+0x288
        add.w   d0,d0
        add.w   d0,d0
        adda.l  d0,a1
        clr.l   d1
        move.w  (a1)+,d1
        adda.l  d1,a2
        move.w  2(a0),d4
        move.w  4(a0),d5
        subi.w  #69,d4
        addi.w  #13,d5
        clr.l   d2
