        clr.w   d3
        move.b  d2,d3
        lsr.w   #8,d2
        move.w  d2,d1
        add.w   d1,d1
        add.w   d1,d1
        subq.w  #1,d3
        subq.w  #1,d2
        tst.w   ARC_WRAM+0x3824
        bne     no_flip
        move.w  #-14,d0
        sub.w   d4,d0
        neg.w   d0
        andi.w  #0x1FF,d0
        move.w  ARC_WRAM+0x28E8,d4
        swap    d4
        move.b  ARC_WRAM+0x288,d4
1:      movea.l a2,a5
        movea.w d3,a1
        swap    d4
        move.w  d4,d6
        swap    d4
        sub.w   d5,d6
        andi.w  #0xFF,d6
2:      tst.w   2(a2)
        beq.s   4f
        move.w  (a2),d7
        andi.w  #0xFF00,d7
        or.w    d6,d7
        move.w  d7,(a3)
        addq.l  #4,a3
        move.l  (a2),d7
        swap    d7
        btst    #6,(a0)
        beq.s   3f
        lsr.b   #2,d7
        andi.b  #0x30,d7
        or.b    d4,d7
        add.b   d7,d7
        add.b   d7,d7
3:      eori.w  #0x20,d7
        lsl.w   #8,d7
        or.w    d0,d7
        swap    d7
        addi.w  #0x2E00,d7
        move.l  d7,(a3)+
        addq.w  #1,(a4)
4:      adda.l  d1,a2
        subi.w  #16,d6
        dbra    d3,2b
        move.w  a1,d3
        movea.l a5,a2
        addq.l  #4,a2
        addi.w  #16,d0
        dbra    d2,1b
        addq.l  #6,a0
