        addi.w  #396,d0
        andi.w  #0x1FF,d0
        move.w  ARC_WRAM+0x28E8,d4
        swap    d4
        move.b  ARC_WRAM+0x288,d4
1:      movea.l a2,a5
        movea.w d3,a1
        swap    d4
        move.w  d4,d6
        swap    d4
        sub.w   d5,d6
        subi.w  #234,d6
        neg.w   d6
        andi.w  #0xFF,d6
2:      tst.w   2(a2)
        beq.s   4f
        move.w  (a2),d7
        andi.w  #0xFF00,d7
        or.w    d6,d7
        eori.w  #0xC000,d7
        move.w  d7,(a3)
        addq.w  #4,a3
        move.l  (a2),d7
        swap    d7
        btst    #6,(a0)
        beq.s   3f
        lsr.b   #2,d7
        andi.b  #0x30,d7
