* nat_txt (jmp at 0x12172): the arcade's string printer, which appends one sprite-list entry per
* character (code, x/y) and handles the control codes 1-9 in between, translated with the variables
* addressed off a3 (FEF400) and the codes dispatched at once instead of through a chain of nine compares.
* Same memory and register effects as the original (a3 kept).
        .global nat_txt
        .equ    TX,     ARC_WRAM+0x3400
nat_txt:
        move.l  a3,-(sp)
        lea     TX,a3
nt_loop:
        move.w  0xF4(a3),d0
        andi.w  #0x7F,d0
        cmpi.w  #100,d0
        bne.s   1f
        move.w  0x11A(a3),d0            /* code 9 mode: stop after the given count */
        cmp.w   0x124(a3),d0
        beq     nt_end
1:      clr.w   d0
        move.b  (a5),d0
        cmpi.w  #9,d0
        bhi.s   nt_char
        add.w   d0,d0
        move.w  nt_tab(pc,d0.w),d0
        jmp     nt_tab(pc,d0.w)
nt_tab: .word   nt_char-nt_tab, nt_c1-nt_tab, nt_c2-nt_tab, nt_c3-nt_tab, nt_c4-nt_tab
        .word   nt_c5-nt_tab, nt_c6-nt_tab, nt_c7-nt_tab, nt_c8-nt_tab, nt_c9-nt_tab
nt_char:
        movea.l 0xF6(a3),a2
        clr.w   d0
        move.b  (a5),d0
        add.w   0x11E(a3),d0
        add.w   0xF2(a3),d0
        move.w  0xF4(a3),d1
        andi.w  #0x7F,d1
        add.w   d1,d0
        move.w  d0,(a2)+
        move.l  0xEE(a3),(a2)+
        move.l  a2,0xF6(a3)
        addq.w  #1,0x11A(a3)
        move.w  0x11A(a3),d1
        cmp.w   0x114(a3),d1
        bne.s   2f
        move.w  0x10C(a3),0x10A(a3)
        bra.s   3f
2:      cmp.w   0x116(a3),d1
        bne.s   3f
        move.w  0x112(a3),0x10E(a3)
3:      clr.w   d0
        move.b  (a5)+,d0
        move.w  0xF4(a3),d1
        andi.w  #0x7F,d1
        add.w   d1,d0
        add.w   d0,d0
        lea     0xEFC46,a1
        move.w  0xEE(a3),d1
        add.w   (a1,d0.w),d1
        add.w   0x10A(a3),d1
        move.w  d1,0xEE(a3)
        move.w  0xF0(a3),d1
        add.w   0x10E(a3),d1
        move.w  d1,0xF0(a3)
        bra     nt_loop
nt_c3:  move.w  0xF4(a3),d0             /* end of the string (d0 as the original leaves it) */
        andi.w  #0x7F,d0
nt_end:                                 /* 0x121DC */
        clr.w   0x10A(a3)
        clr.w   0x10E(a3)
        clr.w   0x114(a3)
        clr.w   0x116(a3)
        clr.w   0x11A(a3)
        andi.w  #0xFF80,0xF4(a3)
        movea.l (sp)+,a3
        rts
nt_c1:  addq.l  #1,a5                   /* x, y */
        clr.l   d0
        move.b  (a5)+,d0
        add.w   d0,d0
        swap    d0
        move.b  (a5)+,d0
        add.w   d0,d0
        move.l  d0,0xEE(a3)
        bra     nt_loop
nt_c2:  addq.l  #1,a5                   /* palette */
        clr.w   d0
        move.b  (a5)+,d0
        ror.w   #6,d0
        move.w  d0,0xF2(a3)
        bra     nt_loop
nt_c4:  addq.l  #1,a5                   /* x step */
        clr.w   d0
        move.b  (a5)+,d0
        ext.w   d0
        move.w  d0,0x10A(a3)
        bra     nt_loop
nt_c5:  addq.l  #1,a5                   /* position from the table at FEF52A */
        clr.w   d0
        move.b  (a5)+,d0
        lsl.w   #2,d0
        lea     TX+0x12A,a1
        adda.w  d0,a1
        move.l  (a1),0xEE(a3)
        bra     nt_loop
nt_c6:  addq.l  #1,a5
        clr.w   d0
        move.b  (a5)+,d0
        lsl.w   #2,d0
        lea     TX+0x146,a1
        adda.w  d0,a1
        move.b  (a1),d0
        ext.w   d0
        move.w  d0,0x10A(a3)
        move.b  1(a1),d0
        ext.w   d0
        move.w  d0,0x10C(a3)
        move.b  2(a1),0x115(a3)
        bra     nt_loop
nt_c7:  addq.l  #1,a5                   /* y step */
        clr.w   d0
        move.b  (a5)+,d0
        ext.w   d0
        move.w  d0,0x10E(a3)
        bra     nt_loop
nt_c8:  addq.l  #1,a5
        clr.w   d0
        move.b  (a5)+,d0
        lsl.w   #2,d0
        lea     TX+0x146,a1
        adda.w  d0,a1
        move.b  (a1),d0
        ext.w   d0
        move.w  d0,0x10E(a3)
        move.b  1(a1),d0
        ext.w   d0
        move.w  d0,0x112(a3)
        move.b  2(a1),0x117(a3)
        bra     nt_loop
nt_c9:  addq.l  #1,a5
        andi.w  #0xFF80,0xF4(a3)
        ori.w   #100,0xF4(a3)
        bra     nt_loop

* strip_win: a0 -> source pair, a1 -> map cell of a column in the window.  Preserves every register.
strip_win:
        movem.l d0-d2/a0-a2,-(sp)
        move.l  (a0),d0
        movea.l a1,a0
        jsr     vram_store
        movem.l (sp)+,d0-d2/a0-a2
        rts

* anim_scan (jmp at 0x9E00): every 12 frames the arcade steps the animated tiles of layer 0 in the
* 24 x 15 cells around the view (codes with code & $1F80 = $0800 take the next code from the table at
* $F01FC, $0A80 from $F05FC; attribute bit 6 selects the second half of the table, codes >= 90 within
* the group stay).  Same cells and stores as the original loop, with a byte table on the high byte of
* the code to skip the other cells quickly.  d0 = first cell offset; continues at 0x9E92 (d5 kept).
        .global anim_scan
anim_scan:
        movea.l #ARC_VRAM,a0
        lea     anim_hi,a2
        moveq   #14,d3
1:      moveq   #23,d2
        moveq   #0,d4
2:      move.b  (a0,d0.w),d4            /* high byte of the code */
        tst.b   (a2,d4.w)
        bne.s   5f
3:      addq.b  #4,d0
        dbra    d2,2b
        subi.b  #96,d0
        addi.w  #256,d0
        andi.w  #8191,d0
        dbra    d3,1b
        jmp     0x9E92
5:      move.w  (a0,d0.w),d1            /* code */
        move.w  d1,d4
        andi.w  #0x1F80,d4
        lea     0xF01FC,a1
        cmpi.w  #0x0800,d4
        beq.s   6f
        lea     0xF05FC,a1
        cmpi.w  #0x0A80,d4
        bne.s   9f
6:      andi.w  #127,d1
        cmpi.w  #90,d1
        bge.s   9f
        btst    #6,3(a0,d0.w)
        beq.s   7f
        bset    #7,d1
7:      add.w   d1,d1
        add.w   d1,d1
        movem.l d0-d3/a0-a2,-(sp)
        move.l  (a1,d1.w),d1
        lea     (a0,d0.w),a0
        move.l  d1,d0
        jsr     vram_store
        movem.l (sp)+,d0-d3/a0-a2
9:      moveq   #0,d4
        bra.s   3b
* anim_hi: 1 for the high bytes of the codes that anim_scan has to look at ($08 / $0A in bits 12-8)
anim_hi:
        .set    i,0
        .rept   256
        .byte   ((i & 0x1F) == 0x08) | ((i & 0x1F) == 0x0A)
        .set    i,i+1
        .endr
        .even
* 0x11FDC / 0x11FF2: fill a layer with the empty tile pair (0xDF64C / 0xDF650, decrypted at build time)
clear_l1:
        lea     ARC_VRAM+0x2000,a0
        move.l  0xDF64C,d0
        bsr     clear_fill
        lea     rt_col_loaded+24,a0
        bra     clear_inval
clear_l0:
        lea     ARC_VRAM,a0
        move.l  0xDF650,d0
        bsr     clear_fill
        lea     rt_col_loaded,a0
clear_inval:
        move.b  #2*NCOLSPR,rt_cl_budget
        st      rt_col_inval
        moveq   #NCOLSPR-1,d0
1:      move.b  #0xFF,(a0)+             /* column sprites reload at the next frame */
        dbra    d0,1b
        rts
clear_fill:
        movem.l d1-d7,-(sp)
        move.l  d0,d1
        move.l  d0,d2
        move.l  d0,d3
        move.l  d0,d4
        move.l  d0,d5
        move.l  d0,d6
        move.l  d0,d7
        move.w  #255,d0
2:      movem.l d1-d7,(a0)
        move.l  d1,28(a0)
        lea     32(a0),a0
        dbra    d0,2b
        movem.l (sp)+,d1-d7
        rts
